package com.campusevents.util;
import java.sql.*;import java.time.*;
public final class DatabaseInitializer {private DatabaseInitializer(){}public static void initialize()throws Exception{String[] ddl={"CREATE TABLE IF NOT EXISTS users(user_id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE COLLATE NOCASE,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('STUDENT','ADMIN')))","CREATE TABLE IF NOT EXISTS students(student_id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL UNIQUE REFERENCES users(user_id) ON DELETE CASCADE,college_id TEXT NOT NULL UNIQUE,department TEXT NOT NULL,academic_year INTEGER NOT NULL CHECK(academic_year BETWEEN 1 AND 6),phone TEXT NOT NULL)","CREATE TABLE IF NOT EXISTS admins(admin_id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL UNIQUE REFERENCES users(user_id) ON DELETE CASCADE)","CREATE TABLE IF NOT EXISTS organizers(organizer_id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,phone TEXT)","CREATE TABLE IF NOT EXISTS categories(category_id INTEGER PRIMARY KEY AUTOINCREMENT,category_name TEXT NOT NULL UNIQUE)","CREATE TABLE IF NOT EXISTS events(event_id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,description TEXT NOT NULL,category_id INTEGER NOT NULL REFERENCES categories(category_id),organizer_id INTEGER NOT NULL REFERENCES organizers(organizer_id),event_date TEXT NOT NULL,start_time TEXT NOT NULL,end_time TEXT NOT NULL,venue TEXT NOT NULL,registration_deadline TEXT NOT NULL,capacity INTEGER NOT NULL CHECK(capacity>0),status TEXT NOT NULL CHECK(status IN ('UPCOMING','ONGOING','COMPLETED','CANCELLED')))","CREATE TABLE IF NOT EXISTS registrations(registration_id TEXT PRIMARY KEY,student_id INTEGER NOT NULL REFERENCES students(student_id),event_id INTEGER NOT NULL REFERENCES events(event_id),registration_date TEXT DEFAULT CURRENT_TIMESTAMP,status TEXT NOT NULL CHECK(status IN ('CONFIRMED','CANCELLED','WAITLISTED')),UNIQUE(student_id,event_id))"};try(Connection c=DatabaseConnection.get();Statement s=c.createStatement()){for(String q:ddl)s.execute(q);}seed();}private static void seed()throws Exception{try(Connection c=DatabaseConnection.get()){try(PreparedStatement p=c.prepareStatement("INSERT OR IGNORE INTO users(name,email,password_hash,role) VALUES('Campus Administrator','admin@campus.local',?,'ADMIN')")){p.setString(1,PasswordUtil.hash("Admin@123"));p.executeUpdate();}try(Statement s=c.createStatement()){s.executeUpdate("INSERT OR IGNORE INTO admins(user_id) SELECT user_id FROM users WHERE email='admin@campus.local'");for(String x:new String[]{"Technical","Cultural","Sports","Workshop","Hackathon","Seminar"})try(PreparedStatement p=c.prepareStatement("INSERT OR IGNORE INTO categories(category_name) VALUES(?)")){p.setString(1,x);p.executeUpdate();}s.executeUpdate("INSERT OR IGNORE INTO organizers(name,email) VALUES('Campus Events Committee','events@campus.local')");}try(Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT COUNT(*) FROM events")){if(r.next()&&r.getInt(1)==0){try(PreparedStatement p=c.prepareStatement("INSERT INTO events(title,description,category_id,organizer_id,event_date,start_time,end_time,venue,registration_deadline,capacity,status) VALUES(?,?,(SELECT category_id FROM categories WHERE category_name='Technical'),(SELECT organizer_id FROM organizers LIMIT 1),?,?,?,?,?,?,'UPCOMING')")){p.setString(1,"Campus Innovation Hackathon");p.setString(2,"Build practical solutions with other students.");p.setString(3,LocalDate.now().plusDays(14).toString());p.setString(4,"09:00");p.setString(5,"18:00");p.setString(6,"Innovation Lab");p.setString(7,LocalDate.now().plusDays(10).toString());p.setInt(8,80);p.executeUpdate();}}}}}}
